const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = () => globalThis.crypto?.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const num = x => x == null || String(x).trim() === '' ? null : (Number.isFinite(Number(x)) ? Number(x) : null);
/** Parse explicitly supplied frequency/value pairs without coercing missing cells to zero. */
export function parseSamplePairs(input, {maxSamples=5000}={}) {
  const source=String(input ?? '').trim();
  if(!source) throw new Error('Enter frequency and value pairs.');
  const rows=source.split(/\r?\n/);
  if(rows.length>maxSamples) throw new Error(`Enter no more than ${maxSamples} samples.`);
  const number='[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][+-]?\\d+)?';
  const pair=new RegExp(`^(${number})(?:\\s*,\\s*|\\s+)(${number})$`);
  let previous=0;
  return rows.map(row=>{const match=row.trim().match(pair); if(!match) throw new Error('Use exactly one frequency and value per line.'); const frequency=Number(match[1]),value=Number(match[2]); if(!Number.isFinite(frequency)||frequency<=previous||frequency>3000||!Number.isFinite(value)) throw new Error('Use increasing positive frequencies up to 3000 MHz and finite values.'); previous=frequency; return [frequency,value];});
}
const fmt = x => x == null || !Number.isFinite(Number(x)) ? '—' : Number(x).toFixed(1);
const options = (items, selected) => items.map(([v,l]) => `<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(l)}</option>`).join('');
const field = (label, name, value='', type='number', extra='') => `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${type==='number' && !extra.includes('step=')?'step="any"':''} ${extra}></label>`;
const button = (text, action, cls='') => `<button type="button" class="${cls}" data-action="${action}">${text}</button>`;

export function removeStation(job,nodeId) {
  job.edges=job.edges.filter(e=>e.from!==nodeId && e.to!==nodeId);
  job.nodes=job.nodes.filter(n=>n.id!==nodeId);
  for(const key of Object.keys(job.portSweeps||{})) if(key.startsWith(`${nodeId}::`)) delete job.portSweeps[key];
  if(job.placements) delete job.placements[nodeId];
}
export function applyMapDraft(job,draft,addCandidates) {
  if(job.map?.sha256===draft.sha256) return false;
  for(const node of job.nodes) delete node.map;
  for(const edge of job.edges) if(edge.mapSourceHash) edge.confirmed=false;
  job.placements={};
  job.map={sha256:draft.sha256,pages:draft.pages.map(p=>({
    pageNumber:p.pageNumber,width:p.width,height:p.height,viewBox:p.viewBox,
    rotation:p.rotation,userUnit:p.userUnit,viewportTransform:p.viewportTransform,
    symbols:(p.symbols||[]).map(s=>({id:s.id,labelBounds:s.labelBounds}))
  }))};
  if(addCandidates) {
    const ids=new Map();
    for(const candidate of draft.nodes||[]) {
      const node={...candidate,id:id(),name:candidate.name||candidate.tag||'Map candidate',tag:candidate.tag||'',kind:candidate.kind||'passive',modelId:'',settings:{}};
      if(candidate.map) node.map={...candidate.map,confirmed:false};
      ids.set(candidate.id,node.id); job.nodes.push(node);
    }
    for(const edge of draft.edges||[]) if(ids.has(edge.from)&&ids.has(edge.to)) job.edges.push({...edge,id:id(),from:ids.get(edge.from),to:ids.get(edge.to),port:'',cableId:'',lengthFt:null,confirmed:false,mapSourceHash:draft.sha256});
  }
  return true;
}

